def max_product(num_str: str, N: int, K: int) -> int:
    if K < 1 or N < K + 1:
        return 0

    dp = [0] * (N + 1)
    dp[N] = int(num_str[N - 1])

    for i in range(N - 1, -1, -1):
        max_current = int(num_str[i])
        min_current = int(num_str[i])
        max_product = max_current

        for j in range(i + 1, min(i + K, N + 1)):
            if num_str[j - 1] == '0':
                max_current, min_current = 1, 1
            else:
                max_current, min_current = max(int(num_str[j - 1]) * max_current, max_current * int(num_str[j - 1])), min(int(num_str[j - 1]) * min_current, min_current * int(num_str[j - 1]))

