def string_transformation(A: str, B: str, rules: List[tuple]) ->Union[int, str]:
    def get_all_transformation(A: str, rules: List[tuple]) -> List[str]:
        transformations = []
        for rule in rules:
            for i, cha in enumerate(A):
                if cha == rule[0]:
                    transformations.append(A[:i] + rule[1] + A[i + 1:])
        return transformations

    queue = deque([(A, 0)])
    visited = set([A])
    while queue:
        current_str, level = queue.popleft()
        if current_str == B:
            return level
        next_transformations = get_all_transformation(current_str, rules)
        for next_str in next_transformations:
            if next_str not in visited:
                visited.add(next_str)
                queue.append((next_str, level + 1))
        if level >= 10:
            return "NO ANSWER!"
    return "NO ANSWER!"

def calculate_score(system, points):
    if system not in [11, 21]:
        raise ValueError("System points must be 11 or 21.")

    score_list = []
    game_score = 0
    opponent_score = 0

    for i, point in enumerate(points):
        game_score += int(point)

        if game_score >= system:
            if game_score > opponent_score + 2:
                score_list.append(f"{game_score - 2}:{opponent_score + 2}")
            else:
                score_list.append(f"{game_score - opponent_score}:0")
            game_score = 0
            opponent_score = 0

    return score_list

