from itertools import combinations

def minimum_students_to_leave(heights):
    n_students = len(heights)
    min_students_to_leave = n_students

    for r in range(1, n_students // 2 + 1): 
        combinations_list = list(combinations(range(n_students), r))
        for leaves in combinations_list:
            start_index = min(leaves)
            queue = deque()
            for i in range(start_index - 1, -1, -1):
                queue.append(i)
                while queue and queue[0] != i:
                    queue.append(queue.popleft())
            has_continue = True
            while has_continue:
                has_continue = False
                can_insert_at = n_students - 1
                while queue and queue[0] != can_insert_at:
                    queue.append(queue.popleft())
                if queue and heights[can_insert_at] >= heights[queue[0]]:
                    continue
                else:
                    has_continue = True
                    heights[can_insert_at] = heights[queue.popleft()]
                    mark_department = queue.pop()
                    while queue and queue[0] != mark_department:
                        queue.append(queue.popleft())
            for i in range(n_students - 1, start_index, -1):
                queue.append(i)
                while queue and queue[0] != i:
                    queue.append(queue.popleft())
            if queue: 
                min_students_to_leave = min(min_students_to_leave , r)
    return min_students_to_leave

def hanoi_double_iterative(n: int) -> int:
    # Base cases for the recurrence relation
    if n == 1:
        return 2
    elif n == 2:
        return 6
    elif n == 3:
        return 14

    # Recursive relation for n discs
    total_moves = 0
    intermediate_moves = 0

    for i in range(1, n + 1):
        if i == 1:
            total_moves += 2 ** (i - 1)
        elif i == 2:
            intermediate_moves = 2 ** (i - 1)
        else:
            total_moves += intermediate_moves

    return total_moves
